import{_ as o,l as r,o as e,c as s,v as i,p as l,x as t,d as c,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SVAR 识别","description":"","frontmatter":{"title":"SVAR 识别","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/svar-identification.md","filePath":"econ/svar-identification.md","lastUpdated":1789023840000}'),h={name:"econ/svar-identification.md"};function p(E,a,_,u,A,R){const n=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="svar-识别" tabindex="-1">SVAR 识别 <a class="header-anchor" href="#svar-识别" aria-label="Permalink to &quot;SVAR 识别&quot;">​</a></h1><div class="epigraph"><p>简化式残差是一锅冲击的线性组合；没有额外限制，谈不上「货币政策冲击的脉冲」。</p><footer>—— Sims, Macroeconomics and Reality, Econometrica 1980；Christiano, Eichenbaum and Evans 对货币冲击的递归识别；Uhlig 符号限制</footer></div><p><a href="/econ/business-cycle-facts">上一课</a>给出共动，并声明共动不命名冲击。本课缺口是<strong>识别</strong>：从 VAR 的 \\(\\Sigma\\) 走到有标签的结构冲击。不重列事实表，不把 DSGE 先验当成唯一识别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Sims：宏观是联立的，OLS 的「谁回归谁」不可当成因果。VAR \\(Y_t=B(L)Y_{t-1}+u_t\\)，\\(u_t=A_0^{-1}\\varepsilon_t\\)。识别 \\(A_0\\) 需要与自由参数同样多的限制：短期递归（Cholesky）、长期（Blanchard–Quah）、符号、外部工具。Christiano–Eichenbaum–Evans：把政策利率放在某顺序上，假设某些变量对货币冲击的同期反应为零。缺口是：IRF 的形状来自限制，不是来自数据单独承认。</p><p><span class="marginnote">Sims, <em>Econometrica</em> 48(1), 1980。Ramey 的手册章节把货币、财政识别的文献收成一张地图。本课不进高频期货，那是再后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计简化式，施加 \\(A_0\\) 限制，画 \\(\\partial Y_{t+h}/\\partial\\varepsilon\\)。递归顺序是零限制的特例，对排序敏感。符号限制给出集合识别：许多 IRF 兼容「紧缩后物价不升」等不等式。外部工具（Stock–Watson、Mertens–Ravn）用代理变量与 \\(\\varepsilon\\) 相关、与其它冲击无关，把识别从 \\(A_0\\) 的零改成矩。DSGE 的 IRF 是另一套：全部限制来自模型。两套对得上才互相撑腰，对不上先查趋势、信息集与冲击定义。</p>',8)),(e(),l(m,null,{default:t(()=>[d(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RED%5B%22%E7%AE%80%E5%8C%96%E5%BC%8F%20u%22%5D%20--%3E%20ID%5B%22%E9%99%90%E5%88%B6%20A0%22%5D%0A%20%20ID%20--%3E%20IRF%5B%22%E7%BB%93%E6%9E%84%20IRF%22%5D%0A%20%20ID%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%20%2F%20%E9%95%BF%E6%9C%9F%20%2F%20%E7%AC%A6%E5%8F%B7%20%2F%20%E5%B7%A5%E5%85%B7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>与 BK：SVAR 不要求 DSGE 的鞍点，但要求冲击正交与足够的滞后。滞后截断会把真实动态推进残差，看起来像「冲击」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把正交化当命名。数据只给 \\(uu&#39;\\)；命名来自「谁在同期不反应」或「长期中性」。错误的零限制把真实传导塞进错误的标签——财政乘数、货币传导的符号之争，多半是识别之争。信息：若私人看到而计量经济学家没放进 VAR 的变量，冲击会提前泄露（Ramey 的财政新闻）。后课局部投影用另一套估计 IRF，识别问题不会消失。</p><p><span class="marginnote">Blanchard and Quah, <em>AER</em> 1989：长期中性识别供需。Uhlig, <em>JME</em> 2005：符号限制下的货币冲击。Christiano, Eichenbaum and Evans, <em>Handbook</em> 与 <em>JPE</em> 2005。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把局部投影当 SVAR 的替代哲学（下一课才比估计方法）。不把叙事日期写进 Cholesky。也不估计因子模型的全部因子 VAR。限价簿、Kyle 冲击不是宏观 SVAR 的 \\(\\varepsilon\\)，本栏不写微观结构识别。</p><p>后课默认：结构 IRF 必须声明识别方案；简化式共动不是脉冲。下一课：Jordà 的局部投影如何在识别给定后直接回归地平线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SVAR：简化式残差加限制才成为有标签的冲击。</li><li>递归、长期、符号、外部工具是不同许可证。</li><li>IRF 之争首先是识别之争。</li><li>出处：Sims, <em>Econometrica</em> 1980；CEE；Uhlig <em>JME</em> 2005。</li></ul>',9))])}const v=o(h,[["render",p]]);export{f as __pageData,v as default};
